-- Add a reusable 150-sentence situational deck with highlighted vocabulary and audio.
insert into public.template_decks (slug, name, description, level)
values (
  'du-lich-san-bay-150-cau',
  'Du lịch và sân bay - 150 câu',
  '150 câu tiếng Trung thực tế cho hành trình du lịch và sân bay: làm thủ tục, nhập cảnh, hành lý, phương tiện, khách sạn và tình huống khẩn cấp. Mỗi câu có pinyin, nghĩa tiếng Việt, 1-2 từ mới được highlight và audio tạo sẵn.',
  'Luyện câu'
)
on conflict (slug) do update
set name = excluded.name, description = excluded.description, level = excluded.level;

with target_deck as (
  select id from public.template_decks where slug = 'du-lich-san-bay-150-cau'
)
insert into public.template_sentence_cards (
  template_deck_id, sentence_cn, sentence_pinyin, sentence_vi,
  vocab_json, sentence_audio_url, position
)
select
  target_deck.id, card.sentence_cn, card.sentence_pinyin,
  card.sentence_vi, card.vocab_json::jsonb,
  card.sentence_audio_url, card.position
from target_deck
cross join (
  values
    ('请问候机楼在哪里？', 'Qǐngwèn hòujī lóu zài nǎlǐ?', 'Xin hỏi nhà ga sân bay ở đâu?', '[{"chinese":"候机楼","pinyin":"hòujī lóu","meaning_vi":"nhà ga đến"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-ef3c2654c9bd5330b6a3cea9.mp3', 1),
    ('我需要在哪里办理登机手续？', 'Wǒ xūyào zài nǎlǐ bànlǐ dēngjī shǒuxù?', 'Tôi cần làm thủ tục lên máy bay ở đâu?', '[{"chinese":"办理","pinyin":"bànlǐ","meaning_vi":"làm thủ tục"},{"chinese":"登机手续","pinyin":"dēngjī shǒuxù","meaning_vi":"thủ tục lên máy bay"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-1976ee91998df63d252af1f0.mp3', 2),
    ('请出示您的护照和电子机票。', 'Qǐng chūshì nín de hùzhào hé diànzǐ jīpiào.', 'Xin vui lòng xuất trình hộ chiếu và vé máy bay điện tử.', '[{"chinese":"护照","pinyin":"hùzhào","meaning_vi":"hộ chiếu"},{"chinese":"电子机票","pinyin":"diànzǐ jīpiào","meaning_vi":"vé máy bay điện tử"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-2251849c6fd2868a284b4613.mp3', 3),
    ('我想选靠窗的座位。', 'Wǒ xiǎng xuǎn kào chuāng de zuòwèi.', 'Tôi muốn chọn chỗ ngồi cạnh cửa sổ.', '[{"chinese":"靠窗","pinyin":"kào chuāng","meaning_vi":"cạnh cửa sổ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-2dbfd9d9dbb54a441e608459.mp3', 4),
    ('请给我登机牌。', 'Qǐng gěi wǒ dēngjīpái.', 'Xin vui lòng cho tôi thẻ lên máy bay.', '[{"chinese":"登机牌","pinyin":"dēngjīpái","meaning_vi":"thẻ lên máy bay"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-ddc67452d4d9359779927d60.mp3', 5),
    ('请问登机口在哪儿？', 'Qǐngwèn dēngjīkǒu zài nǎr?', 'Xin hỏi cửa ra máy bay ở đâu?', '[{"chinese":"登机口","pinyin":"dēngjīkǒu","meaning_vi":"cửa ra máy bay"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-50f4f9fd56a33953b59b3e22.mp3', 6),
    ('飞机几点开始登机？', 'Fēijī jǐ diǎn kāishǐ dēngjī?', 'Việc lên máy bay bắt đầu lúc mấy giờ?', '[{"chinese":"开始","pinyin":"kāishǐ","meaning_vi":"bắt đầu"},{"chinese":"登机","pinyin":"dēngjī","meaning_vi":"lên máy bay"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-81e41f5f98e9439f20cbff78.mp3', 7),
    ('这儿是安检入口吗？', 'Zhèr shì ānjiǎn rùkǒu ma?', 'Đây có phải là cửa kiểm tra an ninh không?', '[{"chinese":"安检","pinyin":"ānjiǎn","meaning_vi":"kiểm tra an ninh"},{"chinese":"入口","pinyin":"rùkǒu","meaning_vi":"cửa vào"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-5e18c4b28464dcb819d5b666.mp3', 8),
    ('液体和电子设备请单独检查。', 'Yètǐ hé diànzǐ shèbèi qǐng dāndú jiǎnchá.', 'Vui lòng kiểm tra riêng chất lỏng và thiết bị điện tử.', '[{"chinese":"液体","pinyin":"yètǐ","meaning_vi":"chất lỏng"},{"chinese":"电子设备","pinyin":"diànzǐ shèbèi","meaning_vi":"thiết bị điện tử"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-15c6bdba1bf190b018662464.mp3', 9),
    ('我的航班延误了，请问怎么办？', 'Wǒ de hángbān yánwù le, qǐngwèn zěnme bàn?', 'Chuyến bay của tôi bị chậm, xin hỏi phải làm sao?', '[{"chinese":"航班","pinyin":"hángbān","meaning_vi":"chuyến bay"},{"chinese":"延误","pinyin":"yánwù","meaning_vi":"bị chậm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-8af6750da63ea5b8172fb59b.mp3', 10),
    ('如果航班取消，我应该去哪儿？', 'Rúguǒ hángbān qǔxiāo, wǒ yīnggāi qù nǎr?', 'Nếu chuyến bay bị hủy, tôi nên đến đâu?', '[{"chinese":"取消","pinyin":"qǔxiāo","meaning_vi":"hủy"},{"chinese":"应该","pinyin":"yīnggāi","meaning_vi":"nên, phải"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-c93fe22cdd258b9f66813d1b.mp3', 11),
    ('请问在哪里办理改签手续？', 'Qǐngwèn zài nǎlǐ bànlǐ gǎi qiān shǒuxù?', 'Xin hỏi làm thủ tục đổi chuyến ở đâu?', '[{"chinese":"办理","pinyin":"bànlǐ","meaning_vi":"làm thủ tục"},{"chinese":"改签","pinyin":"gǎi qiān","meaning_vi":"đổi chuyến"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-7aac27872ef5896714d212c6.mp3', 12),
    ('我需要找到转机柜台。', 'Wǒ xūyào zhǎodào zhuǎnjī guìtái.', 'Tôi cần tìm quầy trung chuyển.', '[{"chinese":"转机","pinyin":"zhuǎnjī","meaning_vi":"trung chuyển"},{"chinese":"柜台","pinyin":"guìtái","meaning_vi":"quầy"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-21274e51ab6046f4a853b945.mp3', 13),
    ('我的行李超重了，请问怎么办？', 'Wǒ de xínglǐ chāozhòng le, qǐngwèn zěnme bàn?', 'Hành lý của tôi quá cân, xin hỏi xử lý thế nào?', '[{"chinese":"行李","pinyin":"xínglǐ","meaning_vi":"hành lý"},{"chinese":"超重","pinyin":"chāozhòng","meaning_vi":"quá cân"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-0ee74143c65f4ba21f1dc881.mp3', 14),
    ('请问国际航班在哪个柜台值机？', 'Qǐngwèn guójì hángbān zài nǎge guìtái zhí jī?', 'Xin hỏi chuyến bay quốc tế làm thủ tục tại quầy nào?', '[{"chinese":"国际航班","pinyin":"guójì hángbān","meaning_vi":"chuyến bay quốc tế"},{"chinese":"柜台","pinyin":"guìtái","meaning_vi":"quầy"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-d3c97be2cc4a0713fe7dd6ff.mp3', 15),
    ('我可以选择靠过道的座位吗？', 'Wǒ kěyǐ xuǎnzé kào guòdào de zuòwèi ma?', 'Tôi có thể chọn chỗ ngồi cạnh lối đi không?', '[{"chinese":"靠过道","pinyin":"kào guòdào","meaning_vi":"cạnh lối đi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-1195a7d5ea6d70e936082135.mp3', 16),
    ('请帮我打印登机牌。', 'Qǐng bāng wǒ dǎyìn dēngjīpái.', 'Xin hãy giúp tôi in thẻ lên máy bay.', '[{"chinese":"打印","pinyin":"dǎyìn","meaning_vi":"in ấn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-8183be872f78ca5ce5307440.mp3', 17),
    ('安检需要脱鞋和取出电子设备。', 'Ānjiǎn xūyào tuō xié hé qǔchū diànzǐ shèbèi.', 'Kiểm tra an ninh cần cởi giày và lấy thiết bị điện tử ra.', '[{"chinese":"脱鞋","pinyin":"tuō xié","meaning_vi":"cởi giày"},{"chinese":"取出","pinyin":"qǔchū","meaning_vi":"lấy ra"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-8dc49244905cecec500adba1.mp3', 18),
    ('请问航班什么时候起飞？', 'Qǐngwèn hángbān shénme shíhòu qǐfēi?', 'Xin hỏi chuyến bay lúc nào cất cánh?', '[{"chinese":"起飞","pinyin":"qǐfēi","meaning_vi":"cất cánh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-626167de469a32a83add7991.mp3', 19),
    ('我可以在哪里托运行李？', 'Wǒ kěyǐ zài nǎlǐ tuōyùn xínglǐ?', 'Tôi có thể gửi hành lý ký gửi ở đâu?', '[{"chinese":"托运行李","pinyin":"tuōyùn xínglǐ","meaning_vi":"hành lý ký gửi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-f7be2f3f9e3dc11f8c8f12da.mp3', 20),
    ('请问新的登机口在哪里？', 'Qǐngwèn xīn de dēngjīkǒu zài nǎlǐ?', 'Xin hỏi cửa ra máy bay mới ở đâu?', '[{"chinese":"登机口","pinyin":"dēngjīkǒu","meaning_vi":"cửa ra máy bay"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-057ea78c787019f6ef32dfb4.mp3', 21),
    ('航班延误时我该联系哪个工作人员？', 'Hángbān yánwù shí wǒ gāi liánxì nǎge gōngzuò rényuán?', 'Khi chuyến bay bị chậm tôi nên liên hệ nhân viên nào?', '[{"chinese":"工作人员","pinyin":"gōngzuò rényuán","meaning_vi":"nhân viên"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-4011912c950d76a1a5d88fc5.mp3', 22),
    ('我的登机牌有座位号吗？', 'Wǒ de dēngjīpái yǒu zuòwèi hào ma?', 'Thẻ lên máy bay của tôi có số ghế không?', '[{"chinese":"座位号","pinyin":"zuòwèi hào","meaning_vi":"số ghế"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-a38bfe740275275a31cfcb91.mp3', 23),
    ('请问转机流程是怎样的？', 'Qǐngwèn zhuǎnjī liúchéng shì zěnyàng de?', 'Xin hỏi quy trình trung chuyển như thế nào?', '[{"chinese":"流程","pinyin":"liúchéng","meaning_vi":"quy trình"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-549c83425855137d038b9473.mp3', 24),
    ('请帮我改签到其他航班。', 'Qǐng bāng wǒ gǎiqiān dào qítā hángbān.', 'Xin giúp tôi đổi sang chuyến bay khác.', '[{"chinese":"改签","pinyin":"gǎiqiān","meaning_vi":"đổi chuyến"},{"chinese":"航班","pinyin":"hángbān","meaning_vi":"chuyến bay"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-e73e42411a90054a0d224a20.mp3', 25),
    ('请问入境检查在哪个区域？', 'Qǐngwèn rùjìng jiǎnchá zài nǎge qūyù?', 'Xin hỏi khu vực kiểm tra nhập cảnh ở đâu?', '[{"chinese":"入境","pinyin":"rùjìng","meaning_vi":"nhập cảnh"},{"chinese":"检查","pinyin":"jiǎnchá","meaning_vi":"kiểm tra"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-de4b9000f2a2ab73a53a2967.mp3', 26),
    ('请问外国护照通道在哪里？', 'Qǐngwèn wàiguó hùzhào tōngdào zài nǎlǐ?', 'Xin hỏi làn dành cho hộ chiếu nước ngoài ở đâu?', '[{"chinese":"外国护照","pinyin":"wàiguó hùzhào","meaning_vi":"hộ chiếu nước ngoài"},{"chinese":"通道","pinyin":"tōngdào","meaning_vi":"làn đi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-1e22bef5ea98240730f7f42d.mp3', 27),
    ('这是我的护照和有效签证，请查验。', 'Zhè shì wǒ de hùzhào hé yǒuxiào qiānzhèng, qǐng cháyàn.', 'Đây là hộ chiếu và thị thực còn hiệu lực của tôi, xin kiểm tra.', '[{"chinese":"有效签证","pinyin":"yǒuxiào qiānzhèng","meaning_vi":"thị thực còn hiệu lực"},{"chinese":"查验","pinyin":"cháyàn","meaning_vi":"kiểm tra"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-194ea55b6c38e1a86e3602a1.mp3', 28),
    ('我这次旅行是为了旅游观光。', 'Wǒ zhè cì lǚxíng shì wèile lǚyóu guānguāng.', 'Chuyến đi này của tôi là để du lịch tham quan.', '[{"chinese":"旅行","pinyin":"lǚxíng","meaning_vi":"chuyến đi"},{"chinese":"旅游","pinyin":"lǚyóu","meaning_vi":"du lịch"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-55735423666d28263992343c.mp3', 29),
    ('我计划在这里停留十天。', 'Wǒ jìhuà zài zhèlǐ tíngliú shí tiān.', 'Tôi dự định ở đây trong mười ngày.', '[{"chinese":"计划","pinyin":"jìhuà","meaning_vi":"dự định"},{"chinese":"停留","pinyin":"tíngliú","meaning_vi":"đình lưu, tạm trú"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-2387f45fed0772c74baa06f0.mp3', 30),
    ('我的住宿地址是这家酒店。', 'Wǒ de zhùsù dìzhǐ shì zhè jiā jiǔdiàn.', 'Địa chỉ lưu trú của tôi là khách sạn này.', '[{"chinese":"住宿","pinyin":"zhùsù","meaning_vi":"lưu trú"},{"chinese":"地址","pinyin":"dìzhǐ","meaning_vi":"địa chỉ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-638131622e70edcf7748d3fd.mp3', 31),
    ('请问我需要填写入境卡吗？', 'Qǐngwèn wǒ xūyào tiánxiě rùjìng kǎ ma?', 'Xin hỏi tôi có cần điền tờ khai nhập cảnh không?', '[{"chinese":"填写","pinyin":"tiánxiě","meaning_vi":"điền (vào mẫu đơn)"},{"chinese":"入境卡","pinyin":"rùjìng kǎ","meaning_vi":"tờ khai nhập cảnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-2be5ceba67e4fec4a530f9a1.mp3', 32),
    ('请帮我填写这张海关申报单。', 'Qǐng bāng wǒ tiánxiě zhè zhāng hǎiguān shēnbào dān.', 'Xin giúp tôi điền vào tờ khai hải quan này.', '[{"chinese":"海关","pinyin":"hǎiguān","meaning_vi":"hải quan"},{"chinese":"申报","pinyin":"shēnbào","meaning_vi":"khai báo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-b735f023ef47d0459d20faae.mp3', 33),
    ('请问哪些物品需要申报？', 'Qǐngwèn nǎxiē wùpǐn xūyào shēnbào?', 'Xin hỏi những vật phẩm nào cần phải khai báo?', '[{"chinese":"物品","pinyin":"wùpǐn","meaning_vi":"vật phẩm"},{"chinese":"申报","pinyin":"shēnbào","meaning_vi":"khai báo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-fbd83fee43e9444fa5ff6ffc.mp3', 34),
    ('我可以走这条无申报通道吗？', 'Wǒ kěyǐ zǒu zhè tiáo wú shēnbào tōngdào ma?', 'Tôi có thể đi qua làn không khai báo này không?', '[{"chinese":"无","pinyin":"wú","meaning_vi":"không có"},{"chinese":"通道","pinyin":"tōngdào","meaning_vi":"làn đường"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-62f634cb804fcaad93705add.mp3', 35),
    ('请告诉我最近的海关检查点在哪里？', 'Qǐng gàosu wǒ zuìjìn de hǎiguān jiǎnchá diǎn zài nǎlǐ?', 'Xin cho tôi biết điểm kiểm tra hải quan gần nhất ở đâu?', '[{"chinese":"检查点","pinyin":"jiǎnchá diǎn","meaning_vi":"điểm kiểm tra"},{"chinese":"海关","pinyin":"hǎiguān","meaning_vi":"hải quan"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-9b9b741eb0acdb348cc79bd5.mp3', 36),
    ('请问入境表格在哪里领取？', 'Qǐngwèn rùjìng biǎogé zài nǎlǐ lǐngqǔ?', 'Xin hỏi mẫu tờ khai nhập cảnh lấy ở đâu?', '[{"chinese":"表格","pinyin":"biǎogé","meaning_vi":"mẫu đơn"},{"chinese":"领取","pinyin":"lǐngqǔ","meaning_vi":"lấy"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-744e5c856e2c4da2bbd4eb60.mp3', 37),
