    ('请问旅游签证的最长停留时间是多久？', 'Qǐngwèn lǚyóu qiānzhèng de zuìcháng tíngliú shíjiān shì duōjiǔ?', 'Xin hỏi thời gian lưu trú tối đa của thị thực du lịch là bao lâu?', '[{"chinese":"最长","pinyin":"zuìcháng","meaning_vi":"dài nhất"},{"chinese":"停留时间","pinyin":"tíngliú shíjiān","meaning_vi":"thời gian lưu trú"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-312130faefc17fed31001992.mp3', 40),
    ('我持有返程机票，请查验。', 'Wǒ chíyǒu fǎnchéng jīpiào, qǐng cháyàn.', 'Tôi có vé máy bay khứ hồi, xin kiểm tra.', '[{"chinese":"持有","pinyin":"chíyǒu","meaning_vi":"cầm giữ"},{"chinese":"返程机票","pinyin":"fǎnchéng jīpiào","meaning_vi":"vé khứ hồi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-08d14b5ae91f685b5f43f999.mp3', 41),
    ('我需要帮助填写这份入境申请表。', 'Wǒ xūyào bāngzhù tiánxiě zhè fèn rùjìng shēnqǐng biǎo.', 'Tôi cần giúp để điền mẫu đơn xin nhập cảnh này.', '[{"chinese":"帮助","pinyin":"bāngzhù","meaning_vi":"giúp đỡ"},{"chinese":"申请表","pinyin":"shēnqǐng biǎo","meaning_vi":"mẫu đơn xin"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-ddfdb75d22d367b69f0c1af3.mp3', 42),
    ('请告诉我哪些物品必须申报？', 'Qǐng gàosu wǒ nǎxiē wùpǐn bìxū shēnbào?', 'Xin cho tôi biết những vật phẩm nào bắt buộc phải khai báo?', '[{"chinese":"必须","pinyin":"bìxū","meaning_vi":"phải, bắt buộc"},{"chinese":"申报","pinyin":"shēnbào","meaning_vi":"khai báo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-88318d80089da5e82185a87c.mp3', 43),
    ('我携带的行李中有礼品需要申报。', 'Wǒ xiédài de xínglǐ zhōng yǒu lǐpǐn xūyào shēnbào.', 'Hành lý tôi mang theo có quà cần khai báo.', '[{"chinese":"行李","pinyin":"xínglǐ","meaning_vi":"hành lý"},{"chinese":"礼品","pinyin":"lǐpǐn","meaning_vi":"quà tặng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-2357d34479f5ad7eb919bd82.mp3', 44),
    ('请问需要申报的物品要走红色通道吗？', 'Qǐngwèn xūyào shēnbào de wùpǐn yào zǒu hóngsè tōngdào ma?', 'Xin hỏi hàng hóa cần khai báo có phải đi qua làn đỏ không?', '[{"chinese":"申报","pinyin":"shēnbào","meaning_vi":"khai báo"},{"chinese":"红色通道","pinyin":"hóngsè tōngdào","meaning_vi":"làn đỏ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-3bfb705679ef3f680e2361d2.mp3', 45),
    ('我可以使用电子申报通道吗？', 'Wǒ kěyǐ shǐyòng diànzǐ shēnbào tōngdào ma?', 'Tôi có thể sử dụng làn khai báo điện tử không?', '[{"chinese":"使用","pinyin":"shǐyòng","meaning_vi":"sử dụng"},{"chinese":"电子","pinyin":"diànzǐ","meaning_vi":"điện tử"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-f6bcc180713da58f26451c76.mp3', 46),
    ('请问在哪里盖入境章？', 'Qǐngwèn zài nǎlǐ gài rùjìngzhāng?', 'Xin hỏi đóng dấu nhập cảnh ở đâu?', '[{"chinese":"入境章","pinyin":"rùjìngzhāng","meaning_vi":"dấu nhập cảnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-148e480180dce12857977b6f.mp3', 47),
    ('我已经向海关申报了这些物品。', 'Wǒ yǐjīng xiàng hǎiguān shēnbào le zhèxiē wùpǐn.', 'Tôi đã khai báo những hàng hóa này với hải quan.', '[{"chinese":"海关","pinyin":"hǎiguān","meaning_vi":"hải quan"},{"chinese":"申报","pinyin":"shēnbào","meaning_vi":"khai báo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-a5609a666e651e55fb610da6.mp3', 48),
    ('请问入境时需要接受健康检查吗？', 'Qǐngwèn rùjìng shí xūyào jiēshòu jiànkāng jiǎnchá ma?', 'Xin hỏi khi nhập cảnh có cần qua kiểm tra sức khỏe không?', '[{"chinese":"健康","pinyin":"jiànkāng","meaning_vi":"sức khỏe"},{"chinese":"检查","pinyin":"jiǎnchá","meaning_vi":"kiểm tra"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-d445777623355b45b9017b49.mp3', 49),
    ('我只带了自用物品，没有需要申报的。', 'Wǒ zhǐ dài le zìyòng wùpǐn, méiyǒu xūyào shēnbào de.', 'Tôi chỉ mang theo đồ dùng cá nhân, không có vật phẩm cần khai báo.', '[{"chinese":"自用","pinyin":"zìyòng","meaning_vi":"dùng cho cá nhân"},{"chinese":"物品","pinyin":"wùpǐn","meaning_vi":"vật phẩm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/du-lich-san-bay-150-cau/sentence-2a51aa84db612e8f2dbb4c2c.mp3', 50),
